-- Goat Funded Trader current selector offers and first-party help-center models.
-- Captured 2026-09-28. Selector-visible offers are published; help-center-only
-- products stay in review until current checkout availability is reconfirmed.
set search_path = bullish_banana, extensions, public;

insert into bullish_banana.firms (name, slug, description, website_url, status, market_type)
values ('Goat Funded Trader', 'goat-funded-trader', 'A simulated Forex evaluation and instant-funding provider with account-size-specific challenges and reward rules.', 'https://www.goatfundedtrader.com/', 'published', 'forex')
on conflict (slug) do update
set name = excluded.name, description = excluded.description, website_url = excluded.website_url,
    status = case when bullish_banana.firms.status = 'published' then 'published' else excluded.status end,
    updated_at = now();

insert into bullish_banana.firm_markets (firm_id, market_type)
select id, 'forex' from bullish_banana.firms where slug = 'goat-funded-trader'
on conflict (firm_id, market_type) do nothing;

insert into bullish_banana.firm_profiles (firm_id, country_code, legal_entity_name, supported_assets, profile_details)
select id, 'HK', 'Wishes Tower International Limited', array['Forex','Crypto','Indices','Metals','Commodities']::text[],
  '{"established_year":null,"operator_disclosure":"Current site footer identifies Goat Funded Trader as a trade name of Wishes Tower International Limited (Hong Kong, company 76428795) and Goat Funded LTD (Saint Lucia, company 2025-00240) as the provider of the simulated trading services. Preserve both disclosed roles; the public terms and service-provider disclosure should be reconciled before presenting one entity as the sole operator.","service_model":"The current legal disclosure describes demo/simulated accounts and evaluation services.","platforms_note":"The public selector offers platform choices, but model-, size-, and region-specific availability was not reliably mapped. Do not infer platform support.","eligibility_note":"The public footer says MT5 is not intended for U.S. citizens/residents and should not be used where unlawful. Complete restricted-country list not confirmed.","fee_refund_conflict":"The selector labels the fee 100% refundable; Terms contain no-refund wording. Eligibility and conditions need reconciliation before describing a universal refund.","current_product_scope":"Six purchase combinations visible in the current Forex model selector: 1-Step GOAT, 2-Step GOAT, 2-Step Standard, Instant HERO, Instant GOAT, and Instant PREMIUM. Other Help Center model articles are staged for availability review."}'::jsonb
from bullish_banana.firms where slug = 'goat-funded-trader'
on conflict (firm_id) do update
set country_code = excluded.country_code, legal_entity_name = excluded.legal_entity_name,
    supported_assets = excluded.supported_assets,
    profile_details = bullish_banana.firm_profiles.profile_details || excluded.profile_details,
    updated_at = now();

insert into bullish_banana.programs (
  firm_id, name, slug, description, program_type, market_type, status, currency,
  account_sizes, max_leverage, profit_split_percent, payout_frequency,
  minimum_trading_days, news_allowed, weekend_holding_allowed, commercial_details,
  published_at, archived_at
)
select f.id, p.name, p.slug, p.description, p.program_type, 'forex', p.status, 'USD',
       p.account_sizes::jsonb, p.max_leverage, p.profit_split_percent, p.payout_frequency,
       p.minimum_trading_days, null::boolean, null::boolean, p.commercial_details::jsonb,
       case when p.status = 'published' then now() else null end, null
from bullish_banana.firms f
