where f.slug = 'goat-funded-trader'
  and not exists (select 1 from bullish_banana.sources s where s.program_id = p.id and s.source_url = x.url);

insert into bullish_banana.affiliate_destinations (firm_id, program_id, kind, label, destination_url, is_primary, status)
select f.id, p.id, 'official_site', 'View ' || p.name || ' at Goat Funded Trader', 'https://www.goatfundedtrader.com/model', true, 'active'
from bullish_banana.firms f
join bullish_banana.programs p on p.firm_id = f.id
where f.slug = 'goat-funded-trader'
  and not exists (select 1 from bullish_banana.affiliate_destinations d where d.program_id = p.id and d.kind = 'official_site');

insert into bullish_banana.data_verifications (firm_id, verified_at, notes)
select id, now(), 'Current Forex selector, live model combinations, legal/footer entity disclosures and Help Center model index reviewed against first-party sources on 2026-09-28. Firm is published; legal-entity roles, platform/country details and refund wording remain explicitly noted.'
from bullish_banana.firms f
where slug = 'goat-funded-trader'
  and not exists (select 1 from bullish_banana.data_verifications v where v.firm_id = f.id);

insert into bullish_banana.data_verifications (program_id, verified_at, notes)
select p.id, now(), case when p.status = 'published'
  then 'Current model selector and official model-specific rules reviewed on 2026-09-28. USD current/list price schedule captured for every selectable size. Promo checkout conditions and fee-refund conflict remain disclosed.'
  else 'Official Help Center article reviewed on 2026-09-28, but the current selector did not expose this model. Record remains in review pending live checkout, sizes, and fees.' end
from bullish_banana.programs p
join bullish_banana.firms f on f.id = p.firm_id
where f.slug = 'goat-funded-trader'
  and not exists (select 1 from bullish_banana.data_verifications v where v.program_id = p.id);
